// Schedule trigger — fetch all active brands for the last 7 days
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{ json: {
  mode: 'weekly',
  brand_name: null,
  brand_id: null,
  period_start: sevenDaysAgo.toISOString().split('T')[0],
  period_end: now.toISOString().split('T')[0],
  period_label: 'This Week'
}}];

// Webhook trigger — optional brand_name or brand_id, optional period_days
const body = $input.first().json.body || $input.first().json;
const brand_name = (body.brand_name || '').trim() || null;
const brand_id = (body.brand_id || '').trim() || null;
const period_days = Math.min(Math.max(parseInt(body.period_days) || 7, 1), 90);

const now = new Date();
const start = new Date(now.getTime() - period_days * 24 * 60 * 60 * 1000);

return [{ json: {
  mode: 'on_demand',
  brand_name,
  brand_id,
  period_start: start.toISOString().split('T')[0],
  period_end: now.toISOString().split('T')[0],
  period_label: period_days === 7 ? 'This Week' : `Last ${period_days} days`
}}];

// Pass through from either entry point
const item = $input.first().json;
return [{ json: item }];

// ============================================================
// AGGREGATE: Per-brand metrics from Projects, Scripts, Invoices
// Uses $() named references to pull data from sequential chain.
// ============================================================
const params = $('Merge Entry Points').first().json;
const brandRecords = $('Fetch Brands').first().json.records || [];

if (brandRecords.length === 0) {
  return [{ json: {
    report_data: null,
    error: 'No active brands found',
    params
  }}];
}

const brands = brandRecords.map(r => ({
  id: r.id,
  brand_name: r.fields.brand_name || r.fields.Name || 'Unknown',
  client_code: r.fields.client_code || '',
  client_name: r.fields.client_name || '',
  status: r.fields.status || 'Active'
}));

const allProjects = ($('Fetch All Projects').first().json.records || []).map(r => ({ id: r.id, ...r.fields }));
const allScripts = ($('Fetch All Scripts').first().json.records || []).map(r => ({ id: r.id, ...r.fields }));
const allInvoices = ($('Fetch All Invoices').first().json.records || []).map(r => ({ id: r.id, ...r.fields }));

const periodStart = params.period_start;
const periodEnd = params.period_end;
const periodLabel = params.period_label;

const startDate = new Date(periodStart + 'T00:00:00Z');
const endDate = new Date(periodEnd + 'T23:59:59Z');
const now = new Date();
const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);

const brandReports = [];
let totalScriptsDelivered = 0;
let totalScriptsInPipeline = 0;
let totalRevenue = 0;
let totalOutstanding = 0;
let totalOverdueInvoices = 0;

for (const brand of brands) {
  // Match projects to brand via brand_name or client_code
  const brandProjects = allProjects.filter(p => {
    const matchName = (p.brand_name || '').toLowerCase() === brand.brand_name.toLowerCase();
    const matchCode = brand.client_code && (p.client_code || '').toLowerCase() === brand.client_code.toLowerCase();
    return matchName || matchCode;
  });

  // Match scripts to brand via project link or brand_name
  const brandProjectIds = brandProjects.map(p => p.id);
  const brandScripts = allScripts.filter(s => {
    const projIds = Array.isArray(s.project_id) ? s.project_id : [s.project_id];
    const matchProject = projIds.some(pid => brandProjectIds.includes(pid));
    const matchBrand = (s.brand_name || '').toLowerCase() === brand.brand_name.toLowerCase();
    return matchProject || matchBrand;
  });

  // Match invoices to brand
  const brandInvoices = allInvoices.filter(inv => {
    const matchName = (inv.brand_name || '').toLowerCase() === brand.brand_name.toLowerCase();
    const matchBrandLink = Array.isArray(inv.brand) ? inv.brand.some(bid => bid === brand.id) : inv.brand === brand.id;
    return matchName || matchBrandLink;
  });

  // --- Scripts delivered in this period ---
  const scriptsDeliveredThisPeriod = brandScripts.filter(s => {
    const status = (s.overall_status || '').toLowerCase();
    if (status !== 'delivered') return false;
    const deliveredAt = s.delivered_at || s.updated_at || s.created_at || '';
    if (!deliveredAt) return true;
    const d = new Date(deliveredAt);
    return d >= startDate && d <= endDate;
  });

  // --- Scripts by status ---
  const statusCounts = {};
  brandScripts.forEach(s => {
    const st = s.overall_status || 'Unknown';
    statusCounts[st] = (statusCounts[st] || 0) + 1;
  });

  const inPipeline = brandScripts.filter(s => {
    const st = (s.overall_status || '').toLowerCase();
    return !['delivered', 'cancelled', 'archived'].includes(st);
  });

  // --- Project status ---
  const activeProjects = brandProjects.filter(p => {
    const st = (p.status || '').toLowerCase();
    return !['completed', 'cancelled', 'archived'].includes(st);
  });
  const completedProjects = brandProjects.filter(p => (p.status || '').toLowerCase() === 'completed');

  // Behind schedule: deadline passed but project not done
  const behindSchedule = brandProjects.filter(p => {
    if (!p.deadline && !p.due_date && !p.end_date) return false;
    const deadline = new Date(p.deadline || p.due_date || p.end_date);
    const st = (p.status || '').toLowerCase();
    return deadline < now && !['completed', 'delivered', 'cancelled', 'archived'].includes(st);
  });

  // --- Revenue: invoices paid this month ---
  const paidThisMonth = brandInvoices.filter(inv => {
    const st = (inv.status || '').toLowerCase();
    if (st !== 'paid') return false;
    const paidDate = inv.paid_date || inv.payment_date || inv.updated_at || '';
    if (!paidDate) return true;
    return new Date(paidDate) >= monthStart;
  });
  const revenue = paidThisMonth.reduce((sum, inv) => sum + (parseFloat(inv.amount) || 0), 0);

  // --- Outstanding: unpaid invoices ---
  const unpaid = brandInvoices.filter(inv => {
    const st = (inv.status || '').toLowerCase();
    return ['pending', 'sent', 'overdue', 'unpaid', 'draft'].includes(st);
  });
  const outstanding = unpaid.reduce((sum, inv) => sum + (parseFloat(inv.amount) || 0), 0);

  // Overdue invoices
  const overdue = unpaid.filter(inv => {
    const dueDate = inv.due_date || inv.deadline || '';
    if (!dueDate) return false;
    return new Date(dueDate) < now;
  });

  totalScriptsDelivered += scriptsDeliveredThisPeriod.length;
  totalScriptsInPipeline += inPipeline.length;
  totalRevenue += revenue;
  totalOutstanding += outstanding;
  totalOverdueInvoices += overdue.length;

  brandReports.push({
    brand_name: brand.brand_name,
    client_code: brand.client_code,
    client_name: brand.client_name,
    scripts_delivered: scriptsDeliveredThisPeriod.length,
    scripts_in_pipeline: inPipeline.length,
    total_scripts: brandScripts.length,
    script_status_breakdown: statusCounts,
    active_projects: activeProjects.length,
    completed_projects: completedProjects.length,
    total_projects: brandProjects.length,
    behind_schedule: behindSchedule.map(p => ({
      name: p.project_name || p.client_code || 'Project',
      status: p.status,
      deadline: p.deadline || p.due_date || p.end_date || 'N/A'
    })),
    revenue_this_month: revenue,
    outstanding_amount: outstanding,
    overdue_invoices: overdue.length,
    overdue_total: overdue.reduce((s, inv) => s + (parseFloat(inv.amount) || 0), 0)
  });
}

function formatINR(amount) {
  if (amount >= 100000) return `Rs ${(amount / 100000).toFixed(1)}L`;
  if (amount >= 1000) return `Rs ${(amount / 1000).toFixed(1)}K`;
  return `Rs ${amount.toFixed(0)}`;
}

const report_data = {
  period_label: periodLabel,
  period_start: periodStart,
  period_end: periodEnd,
  generated_at: now.toISOString(),
  mode: params.mode,
  brand_count: brands.length,
  totals: {
    scripts_delivered: totalScriptsDelivered,
    scripts_in_pipeline: totalScriptsInPipeline,
    revenue_this_month: totalRevenue,
    revenue_formatted: formatINR(totalRevenue),
    outstanding: totalOutstanding,
    outstanding_formatted: formatINR(totalOutstanding),
    overdue_invoices: totalOverdueInvoices
  },
  brands: brandReports
};

return [{ json: { report_data, params } }];

// ============================================================
// Build Gemini prompt for weekly report generation
// ============================================================
const d = $input.first().json;
const rd = d.report_data;

if (!rd) {
  return [{ json: { ...d, gemini_body: null, _skip_gemini: true, report_text: d.error || 'No active brands found. Nothing to report.' } }];
}

const dataBlock = JSON.stringify(rd, null, 2);

const systemPrompt = `You are the reporting assistant for Smashed Agency, a one-person UGC agency run by Vishat. Your job is to write concise, brutally honest weekly reports. No corporate speak. No fluff. Just numbers and actionable insights.

Rules:
- Use Indian Rupee amounts (use lakhs notation like 1.2L for amounts >= 1 lakh, K for thousands)
- Be specific: name brands, give exact counts, mention deadlines
- If something is behind schedule, say so directly with how many days
- If revenue is low or zero, flag it
- Keep the executive summary to 2-3 sentences max — think WhatsApp message to yourself
- Use plain text formatting suitable for Slack (use *bold* for emphasis, bullet points with -)
- Do NOT use markdown headers (no # or ##) — use *SECTION NAME* in bold instead
- The report should fit in one Slack message (under 3000 chars)
- End with 2-3 concrete action items for next week
- If a brand has zero activity, say so in one line — don't pad it
- Mention specific project phases (Research, Scripting, Review, Delivery) not vague "in progress"`;

const userPrompt = `Generate the weekly report for ${rd.period_label} (${rd.period_start} to ${rd.period_end}).

Here is the raw data:

${dataBlock}

Write the report in this structure:

*WEEKLY REPORT — ${rd.period_label.toUpperCase()}*
(${rd.period_start} to ${rd.period_end})

*Executive Summary*
2-3 sentences. Example tone: "Delivered 8 scripts across 3 brands this week. Wheelwash is 2 days behind on Phase 3. Revenue: Rs 1.2L collected, Rs 45K outstanding from 2 overdue invoices."

*Per-Brand Breakdown*
For each brand:
- Scripts delivered this period / in pipeline (with status breakdown)
- Active projects and their current phase
- Behind schedule warnings with days overdue
- If no activity, just say "No activity this period"

*Revenue*
- Collected this month (Rs amount)
- Outstanding (Rs amount)
- Overdue invoices count + total

*Next Week*
- 2-3 specific action items based on the data (e.g., "Clear Wheelwash backlog", "Follow up on Dhan invoice")

Be like a sharp operations manager. Numbers first, opinions second.`;

const body = {
  systemInstruction: { parts: [{ text: systemPrompt }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: { temperature: 0.3, maxOutputTokens: 3000 }
};

return [{ json: { ...d, gemini_body: JSON.stringify(body), _skip_gemini: false } }];

// ============================================================
// Parse Gemini response — with fallback report generation
// ============================================================
const promptData = $('Build Report Prompt').first().json;
const rd = promptData.report_data;

// If we skipped Gemini (no brands)
if (promptData._skip_gemini) {
  return [{ json: {
    report_text: promptData.report_text || 'No data to report.',
    report_data: rd,
    mode: promptData.params.mode
  }}];
}

const raw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';

// Clean thinking tags if Gemini includes them
let reportText = raw
  .replace(/<thinking>[\s\S]*?<\/thinking>/gi, '')
  .trim();

// Fallback: if Gemini returned garbage or empty, build from raw data
if (!reportText || reportText.length < 50) {
  const t = rd.totals;
  const brandLines = rd.brands.map(b => {
    let line = `- *${b.brand_name}*: ${b.scripts_delivered} delivered, ${b.scripts_in_pipeline} in pipeline`;
    if (Object.keys(b.script_status_breakdown).length > 0) {
      const breakdown = Object.entries(b.script_status_breakdown)
        .map(([k, v]) => `${k}: ${v}`).join(', ');
      line += ` (${breakdown})`;
    }
    if (b.behind_schedule.length > 0) {
      const names = b.behind_schedule.map(p => p.name).join(', ');
      line += `\n  BEHIND SCHEDULE: ${names}`;
    }
    if (b.overdue_invoices > 0) {
      line += `\n  OVERDUE: ${b.overdue_invoices} invoice(s), Rs ${b.overdue_total}`;
    }
    return line;
  }).join('\n');

  reportText = `*WEEKLY REPORT — ${rd.period_label.toUpperCase()}*\n`
    + `(${rd.period_start} to ${rd.period_end})\n\n`
    + `*Executive Summary*\n`
    + `Delivered ${t.scripts_delivered} scripts across ${rd.brand_count} brand(s). `
    + `${t.scripts_in_pipeline} scripts still in pipeline. `
    + `Revenue: ${t.revenue_formatted} collected, ${t.outstanding_formatted} outstanding`
    + (t.overdue_invoices > 0 ? ` (${t.overdue_invoices} overdue).` : '.')
    + `\n\n*Per-Brand Breakdown*\n${brandLines}`
    + `\n\n*Revenue*\n- Collected this month: ${t.revenue_formatted}\n- Outstanding: ${t.outstanding_formatted}`
    + (t.overdue_invoices > 0 ? `\n- Overdue invoices: ${t.overdue_invoices}` : '')
    + `\n\n*Next Week*\n- Review pipeline and clear bottlenecks\n- Follow up on outstanding invoices`;
}

return [{ json: {
  report_text: reportText,
  report_data: rd,
  mode: promptData.params.mode
}}];
